def validate_request_data(data):
    """Return *data* after validating the request payload's basic shape.

    Request payloads must be dictionaries whose keys are strings.  Keeping
    this validation separate from request processing makes it harder to
    accidentally process a malformed payload.
    """
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    non_string_keys = [key for key in data.keys() if not isinstance(key, str)]
    if non_string_keys:
        raise TypeError("data keys must be strings")

    return data


def handle_request(data):
    """Validate an incoming API request payload before processing it."""
    validated_data = validate_request_data(data)
    return process(validated_data)

